    // Create a priority queue to hold nodes to be processed, with the start node as the first node
    std::priority_queue<std::pair<float, Node*>> queue;
    queue.push({0, &graph.Nodes()[start_idx]});

    // Create a set to keep track of visited nodes
    std::set<Node*> visited;

    // While there are still nodes in the queue
    while (!queue.empty()) {
        // Get the node with the highest priority (i.e., the node with the lowest f score)
        auto current_node = queue.top().second;
        queue.pop();

        // If this node is the end node, we've found the shortest path
        if (current_node->idx == end_idx) {
            // Reconstruct the path by following the parent pointers
            std::vector<Node> path;
            while (current_node) {
                path.push_back(*current_node);
                current_node = current_node->parent;
            }
            // Return the path in the correct order
            std::reverse(path.begin(), path.end());
            return path;
        }

        // Mark this node as visited
        visited.insert(current_node);

        // For each neighbor of this node that hasn't been visited
        for (auto neighbor : current_node->neighbors) {
            if (visited.find(neighbor) == visited.end()) {
                // Calculate the tentative g score for this neighbor
                float tentative_g_score = current_node->g_value + current_node->distance(*neighbor);

