                    // Update the neighbor's g score, h score, and parent
                    neighbor->g_value = tentative_g_score;
                    neighbor->h_value = neighbor->distance(graph.Nodes()[end_idx]);
                    neighbor->parent = current_node;

                    // Add the neighbor to the queue
                    queue.push({neighbor->g_value + neighbor->h_value, neighbor});
                }
            }
        }
    }

    // If there is no path to the end node, return an empty vector
    return {};
